function s(r){if(!r||r<=0)return"0 bps";const t=["bps","Kbps","Mbps","Gbps","Tbps"];let n=r,o=0;for(;n>=1e3&&o<t.length-1;)n/=1e3,o++;return`${n>=100?Math.round(n):Math.round(n*100)/100} ${t[o]}`}function u(r){if(!r||r<=0)return"0 B";const t=["B","KB","MB","GB","TB","PB"];let n=r,o=0;for(;n>=1024&&o<t.length-1;)n/=1024,o++;return`${Math.round(n*100)/100} ${t[o]}`}function a(r){const t=r.trim().toLowerCase();if(!t||t==="unlimited"||t==="∞"||t==="0")return 0;const n=t.match(/^([0-9.]+)\s*(gbps|mbps|kbps|bps)?$/);if(!n)return-1;const o=parseFloat(n[1]);return isNaN(o)||o<0?-1:Math.round(o*{bps:1,kbps:1e3,mbps:1e6,gbps:1e9}[n[2]??"mbps"])}function f(r){if(!r)return"—";const t=Math.floor((Date.now()-new Date(r).getTime())/1e3);return t<0?"now":t<60?`${t}s ago`:t<3600?`${Math.floor(t/60)}m ago`:t<86400?`${Math.floor(t/3600)}h ago`:`${Math.floor(t/86400)}d ago`}function i(r){const t=Math.floor(r/86400),n=Math.floor(r%86400/3600),o=Math.floor(r%3600/60);return t>0?`${t}d ${n}h`:n>0?`${n}h ${o}m`:`${o}m`}export{i as a,s as b,u as c,f,a as p};
